# Surah Al-Anfal (chapter 8) — part 8: ayat 69-75 (IDs 1229-1235)
SURAH = 8

ENTRIES = {
1229: (
"پس — کھاؤ — جو — مالِ غنیمت — تم نے — حاصل کیا — حلال پاکیزہ — اور — اللہ سے ڈرو — بے شک — اللہ — بخشنے والا مہربان ہے",
"""۱۔ بدر کی غنیمت — مؤمنوں کے لیے حلال — تم کن۔
۲۔ ’’فَكُلُوا مِمَّا غَنِمْتُمْ حَلَالًا طَيِّبًا وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ‘‘ — پس — کھاؤ — جو — مالِ غنیمت — تم نے — حاصل کیا — حلال پاکیزہ — اور — اللہ سے ڈرو — بے شک — اللہ — بخشنے والا مہربان ہے — یعنی بدر کی غنیمت — اللہ کی رحمت سے — حلال — کردی گئی۔
۳۔ عملی سبق: حلال رزق کھاؤ؛ اللہ سے ڈرو۔"""
),
1230: (
"اے نبیؐ — اپنے — اسیروں سے کہو — اگر — اللہ — تمہارے دلوں میں — کوئی بھلائی جانے — وہ — تمہیں — اس — سے بہتر — دے دے جو — تم سے — لیا گیا — اور — تمہیں — بخش دے — اور — اللہ — بخشنے والا مہربان ہے",
"""۱۔ قیدیوں کے لیے توبہ کا دروازہ کھلا۔
۲۔ ’’يَا أَيُّهَا النَّبِيُّ قُل لِّمَن فِي أَيْدِيكُم مِّنَ الْأَسْرَىٰ إِن يَعْلَمِ اللَّهُ فِي قُلُوبِكُمْ خَيْرًا يُّؤْتِكُمْ خَيْرًا مِّمَّا أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ‘‘ — اے نبیؐ — اپنے — اسیروں سے کہو — اگر — اللہ — تمہارے دلوں میں — کوئی بھلائی جانے — وہ — تمہیں — اس — سے بہتر — دے دے جو — تم سے — لیا گیا — اور — تمہیں — بخش دے — اور — اللہ — بخشنے والا مہربان ہے — یعنی اگر قیدی — ایمان لائے — انہیں — دنیا و آخرت کی بہترین نعمتیں ملیں گی۔
۳۔ عملی سبق: قیدیوں کے ساتھ — حسن سلوک — اور — معافی کا موقع — دیں۔"""
),
1231: (
"اور — اگر — وہ — تم سے — خیانت — کرنا چاہیں — تو — انہوں نے — پہلے — اللہ سے — خیانت کی — پس — اس نے — انہیں — تمہارے — قابو — میں — کر دیا — اور — اللہ — جاننے والا حکمت والا ہے",
"""۱۔ قیدیوں کی سابقہ خیانتیں — اللہ کی طرف سے رحمت۔
۲۔ ’’وَإِن يُرِيدُوا خِيَانَتَكَ فَقَدْ خَانُوا اللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ وَاللَّهُ عَلِيمٌ حَكِيمٌ‘‘ — اور — اگر — وہ — تم سے — خیانت — کرنا چاہیں — تو — انہوں نے — پہلے — اللہ سے — خیانت کی — پس — اس نے — انہیں — تمہارے — قابو — میں — کر دیا — اور — اللہ — جاننے والا حکمت والا ہے — یعنی کفار — سابقہ خیانتیں — کر چکے تھے؛ اب — وہ — مؤمنوں کے قابو میں ہیں۔
۳۔ عملی سبق: خیانت کا انجام — ناکامی ہے۔"""
),
1232: (
"بے شک — جنہوں نے — ایمان لایا — ہجرت کی — اور — اللہ کی راہ میں — اپنے مالوں اور جانوں کے ساتھ — جہاد کیا — اور — جنہوں نے — پناہ دی — اور — نصرت کی — یہ — سب — ایک دوسرے کے — کارساز ہیں — اور — جنہوں نے — ایمان لایا — مگر — ہجرت نہیں کی — تمہارا — ان پر — کوئی ولایت نہیں — یہاں تک کہ — وہ — ہجرت کریں — اور — اگر — وہ — دین — میں — تم سے مدد مانگیں — تو — تم پر مدد — کرنا لازم ہے — سوائے اس — قوم کے خلاف — جس سے تمہارا — عہد — ہے — اور — اللہ — تمہارے اعمال — دیکھ رہا ہے",
"""۱۔ ہجرت اور انصار — ایک دوسرے کے ولی۔
۲۔ ’’إِنَّ الَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنفُسِهِمْ فِي سَبِيلِ اللَّهِ وَالَّذِينَ آوَوا وَّنَصَرُوا أُولَٰئِكَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ وَالَّذِينَ آمَنُوا وَلَمْ يُهَاجِرُوا مَا لَكُم مِّن وَلَايَتِهِم مِّن شَيْءٍ حَتَّىٰ يُهَاجِرُوا وَإِنِ اسْتَنصَرُوكُمْ فِي الدِّينِ فَعَلَيْكُمُ النَّصْرُ إِلَّا عَلَىٰ قَوْمٍ بَيْنَكُمْ وَبَيْنَهُم مِّيثَاقٌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ‘‘ — بے شک — جنہوں نے — ایمان لایا — ہجرت کی — اور — اللہ کی راہ میں — اپنے مالوں اور جانوں کے ساتھ — جہاد کیا — اور — جنہوں نے — پناہ دی — اور — نصرت کی — یہ — سب — ایک دوسرے کے — کارساز ہیں — اور — جنہوں نے — ایمان لایا — مگر — ہجرت نہیں کی — تمہارا — ان پر — کوئی ولایت نہیں — یہاں تک کہ — وہ — ہجرت کریں — اور — اگر — وہ — دین — میں — تم سے مدد مانگیں — تو — تم پر مدد — کرنا لازم ہے — سوائے اس — قوم کے خلاف — جس سے تمہارا — عہد — ہے — اور — اللہ — تمہارے اعمال — دیکھ رہا ہے — یعنی مہاجرین اور انصار — ایک دوسرے کے ولی — ہیں — یہاں تک کہ — وہ — ہجرت کریں۔
۳۔ عملی سبق: دین میں مدد — عہد شدہ — قوم کے خلاف نہیں — کی جاتی۔"""
),
1233: (
"اور جنہوں نے — کفر کیا — وہ — ایک دوسرے کے — کارساز ہیں — اگر — تم — ایسا نہ کرو — تو — زمین میں — فتنہ — اور بڑا فساد — ہو گا",
"""۱۔ کفار — ایک دوسرے کے حمایتی؛ مؤمنوں کا اتحاد لازم۔
۲۔ ’’وَالَّذِينَ كَفَرُوا بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَۃٌ فِي الْأَرْضِ وَفَسَادٌ كَبِيرٌ‘‘ — اور جنہوں نے — کفر کیا — وہ — ایک دوسرے کے — کارساز ہیں — اگر — تم — ایسا نہ کرو — تو — زمین میں — فتنہ — اور بڑا فساد — ہو گا — یعنی اگر — مؤمن — ایک نہ ہوں — زمین میں — بڑا فساد پھیل جائے۔
۳۔ عملی سبق: مؤمنوں کا اتحاد — فساد روکنے کی کلید ہے۔"""
),
1234: (
"اور جنہوں نے — ایمان لایا — ہجرت کی — اور — اللہ کی راہ میں — جہاد کیا — اور — جنہوں نے — پناہ دی — اور — نصرت کی — یہی لوگ — حقیقی مؤمن ہیں — انہیں — بخشش — اور عزت کی روزی — ملے گی",
"""۱۔ مہاجرین اور انصار — حقیقی مؤمن۔
۲۔ ’’وَالَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللَّهِ وَالَّذِينَ آوَوا وَّنَصَرُوا أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا لَّهُم مَّغْفِرَۃٌ وَرِزْقٌ كَرِيمٌ‘‘ — اور جنہوں نے — ایمان لایا — ہجرت کی — اور — اللہ کی راہ میں — جہاد کیا — اور — جنہوں نے — پناہ دی — اور — نصرت کی — یہی لوگ — حقیقی مؤمن ہیں — انہیں — بخشش — اور عزت کی روزی — ملے گی — یعنی مہاجرین و انصار — اللہ کی نظر میں — سچے مؤمن ہیں۔
۳۔ عملی سبق: قربانی اور نصرت — ایمان کا — معیار ہے۔"""
),
1235: (
"اور جنہوں نے — بعد میں — ایمان لایا — اور — ہجرت کی — اور — تمہارے ساتھ — جہاد کیا — تو — یہ — تمہارے ہی سے ہیں — اور — قرابت دار — ایک دوسرے — کے — زیادہ حقدار ہیں — اللہ کی کتاب میں — بے شک — اللہ — ہر چیز — کو — جاننے والا ہے",
"""۱۔ بعد والے مؤمنین بھی — تمہارے — ہی ہیں۔
۲۔ ’’وَالَّذِينَ آمَنُوا مِن بَعْدُ وَهَاجَرُوا وَجَاهَدُوا مَعَكُمْ فَأُولَٰئِكَ مِنكُمْ وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِي كِتَابِ اللَّهِ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ‘‘ — اور جنہوں نے — بعد میں — ایمان لایا — اور — ہجرت کی — اور — تمہارے ساتھ — جہاد کیا — تو — یہ — تمہارے ہی سے ہیں — اور — قرابت دار — ایک دوسرے — کے — زیادہ حقدار ہیں — اللہ کی کتاب میں — بے شک — اللہ — ہر چیز — کو — جاننے والا ہے — یعنی ایمان سب کے لیے ہے — مگر وراثت — قرابتداری کے حساب سے — تقسیم ہوگی۔
۳۔ عملی سبق: ایمان — سب — کے لیے ہے؛ وراثت — قرابتداری — کے حساب سے۔"""
),
}
